        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0.0, float(-s.min()))
            s_t = np.log1p(s + shift)
        else:
            s_t, shift = s, 0.0
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo, hi = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme spread is natural, not anomalous'
