        hi_orig = float(np.expm1(hi) - shift) if abs(skew) > 2 else float(hi)
        er = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        for idx in flagged.index:
            if len(anomaly_records) >= 25:
                break
            v = float(df.loc[idx, col])
            sv = float(s_t[idx])
            if sv < q1 - 5 * iqr or sv > q3 + 5 * iqr:
