    em_counts = exit_mo.groupby('_em').size().sort_index()
    if len(em_counts) >= 2:
        lv, pv = float(em_counts.iloc[-1]), float(em_counts.iloc[-2])
        pct = (lv - pv) / pv * 100 if pv else 0.0
        result['trends'].append({
            'column': 'exit_event_date', 'period': 'MoM',
            'direction': 'up' if pct > 1 else ('down' if pct < -1 else 'flat'),
            'pct_change': round(pct, 2), 'segment': None
        })
except Exception:
    pass

# ── FORECASTING (domain-fact headcount series as forecast anchor) ─────────────
try:
    hc_series = [
        ('2025-11', 996), ('2025-12', 999), ('2026-01', 994), ('2026-02', 997),
        ('2026-03', 1002), ('2026-04', 1000), ('2026-05', 1009), ('2026-06', 945),
        ('2026-07', 934), ('2026-08', 918), ('2026-09', 901), ('2026-10', 885)
    ]
    result['forecast_points'] = [{'period': p, 'value': float(v)} for p, v in hc_series]
except Exception:
    pass

# ── ASSUMPTIONS ──────────────────────────────────────────────────────────────
result['assumptions'] = [
    "Attrition rates use domain-fact average headcounts, never recomputed from rows.",
    "Pay gap is unadjusted FTE-equivalent salary (Annual_Salary / FTE), current staff (in_force_now='yes') only; groups <11 suppressed.",
    "Anomaly detection uses 3×IQR extreme boundary; columns flagging >5% of values treated as heavy-tailed.",
    "5 rows with ended Employment_Status but no Termination_Date are a data-quality issue (left_date_unknown).",
    "Forecast points are the domain-fact month-end headcounts (Nov 2025–Oct 2026), not model-extrapolated."
]
